import {ArrowRight,ArrowUpRight,BadgeCheck,BookOpen,Building2,ChartNoAxesCombined,Check,ChevronDown,ChevronRight,ClipboardCheck,Clock3,Compass,Copy,Factory,FileCheck2,FileText,Flame,FlaskConical,FolderOpen,Globe2,GraduationCap,HardHat,Info,Leaf,ListChecks,LockKeyhole,Mail,MapPin,Menu,MessagesSquare,Minus,MoveUpRight,Plus,Printer,Phone,ScanSearch,Search,ShieldCheck,Sparkles,Target,Telescope,UsersRound,Waypoints,Workflow,X,Zap} from 'lucide-react';
const Icons={ArrowRight,ArrowUpRight,BadgeCheck,BookOpen,Building2,ChartNoAxesCombined,Check,ChevronDown,ChevronRight,ClipboardCheck,Clock3,Compass,Copy,Factory,FileCheck2,FileText,Flame,FlaskConical,FolderOpen,Globe2,GraduationCap,HardHat,Info,Leaf,ListChecks,LockKeyhole,Mail,MapPin,Menu,MessagesSquare,Minus,MoveUpRight,Plus,Printer,Phone,ScanSearch,Search,ShieldCheck,Sparkles,Target,Telescope,UsersRound,Waypoints,Workflow,X,Zap};
